  str_quest_base_awards_info_look = "ตัวอย่างรางวัล",
  str_quest_base_story_chapter_index = "บท %s",
  str_quest_base_story_all_chapter_clean = "เควสต์ของทุกบทเสร็จสมบูรณ์แล้ว!",
  str_quest_base_story_current_chapter_clean = "เควสต์ทั้งหมดในบทนี้เสร็จสมบูรณ์แล้ว",
  str_quest_base_story_click_lock_chapter = "ทำเควสต์เนื้อเรื่องก่อนหน้าให้สำเร็จเพื่อปลดล็อก",
  str_quest_base_desc_101 = "โซรอซ การเดินทางของเจ้าจะเริ่มต้นขึ้นที่นี่ สถานการณ์ไม่คาดฝัน ความเปลี่ยนแปลง เหตุร้ายที่อาจไม่ร้ายอย่างที่คิด และการเติบโต... เจ้าจะต้องพบเจอกับความยากลำบากเพื่อให้แข็งแกร่งขึ้น หากหลบเลี่ยงไม่ได้ ก็อ้าแขนรับมันซะ การเผชิญหน้ากับความทุกข์ยากของเจ้าจะไม่สูญเปล่าแน่นอน\n—เบธเลเฮม",
  str_quest_base_desc_102 = "การมาถึงโลกใบนี้เป็นประสบการณ์ที่ยิ่งใหญ่แท้ใช่ไหม? ข้าหวังว่าเจ้าจะรับมือกับวิกฤติการณ์อย่างสงบและมีเหตุผล รักและเอ็นดูสัมพันธ์ของเจ้า ทุกคนและทุกสิ่งที่เจ้าเห็นเป็นส่วนหนึ่งของอัสตรัล และในที่สุดจะกลายเป็นส่วนหนึ่งของออโรรา แม้กระทั่งส่วนหนึ่งของตัวเจ้าเอง... ยอมรับ เข้าใจ ตอบสนอง และเติบโตต่อไป\n-เบธเลเฮม-",
  str_quest_base_desc_103 = "เสียงสะท้อนจากอดีตก้องขึ้นอีกครั้ง พร้อมกับเพื่อนร่วมชาติ ศัตรู และสหายในการรบ จงเตรียมตัวสำหรับสิ่งที่แย่ที่สุดและหวังให้ดีที่สุด ประเมินความเกลียดชังส่วนตัวของคุณต่อภารกิจของกลุ่มใหม่ บทเรียนเหล่านี้สามารถเรียนรู้ได้เฉพาะผ่านเส้นเลือดและน้ำตา\n—เบธเลเฮม",
  str_quest_base_desc_104 = "เอาล่ะ เจ้าเข้าใจเป้าหมายของเจ้าหรือยัง? รับรู้ได้ถึงความเป็นตัวตนจากผู้คนที่อยู่นอกกลุ่มของเจ้าหรือไม่? เบื้องหน้านั่นคือเมืองออโรเรียนสุดท้าย ที่ลอยอยู่บนฟ้า ณ ที่นั่น เจ้าจะได้พบกับสัมพันธ์ใหม่ และก้าวต่อไปอย่างมั่นคงในเส้นทางปัดเป่าความมืด\n—เบธเลเฮม",
  str_quest_base_desc_105 = "แม้จะโดนต่อต้านอย่างไม่ลดละ แต่ก็ยังยืนหยัดต่อสู้ต่อไป ราวกับเป็นสัตว์ร้ายที่สะกดคำว่าถอยไม่เป็น ราวกับผู้กล้าหาญที่สู้จนตัวตายทั้ง ๆ ที่ยังจับดาบไว้มั่นท่ามกลางดินแดนที่ถูกลืม อดีตจะหวนคืนกลับมา เจ้าจะต้องเผชิญหน้ากับความกลัวที่น่าสั่นสะพรึงที่สุด ลองมองไปที่หน้านางชัด ๆ แล้วบอกข้าว่าเจ้าเห็นใครในนั้น?\n—เบธเลเฮม",
  str_quest_base_desc_106 = "หวั่นใจใช่ไหม? อย่างที่ออโรราแนะนำ ตอนนี้คุณอยู่ใกล้ก้นบึ้งแล้ว ห้วงแห่งความขมขื่นและขุ่นเคือง คุกเหล็กที่สร้างจากความล้มเหลวและความอัปยศ แต่ที่นี่เท่านั้นที่คุณจะพบกับความแข็งแกร่งที่แท้จริง—ไม่ใช่เหล็กกล้า แต่วิสัยทัศน์กว้างขวางและจิตใจที่รวมเป็นหนึ่ง\n—เบธเลเฮม",
  str_quest_base_desc_107 = "เรากำลังเข้าสู่ระยะใหม่ของการสนทนาข้ามพื้นที่กันแล้วเคเลสไทต์ คุณคงไม่เข้าใจบทบาทของฉัน และฉันเองก็ไม่สามารถเข้าใจคำพูดที่เป็นนัยหลังคาย ออโรรากำลังค่อย ๆ สลาย และผู้ชายที่สิ้นหวังกำลังกระจายปีกเต็มท้องฟ้าของลูโมโพลิส คุณต้องพิชิตมันหรือถูกพิชิต จบเรื่อง\n-เบธเลเฮม-",
  str_quest_base_desc_108 = "แม้จะอยู่ในเหวที่ลึกที่สุดและมืดมนที่สุด คุณก็จะรอดเพื่อให้คำทำนายเป็นจริง นั่นคือสิ่งที่ฉันเชื่อ และสัญชาตญาณของฉันยืนยันว่าฉันทำตาม ฉวยโอกาสนี้ Caeleste และประณามให้ Black Keep กลับไปยังที่ของมัน!\n—เบธเลเฮม",
  str_quest_base_desc_109 = "บ้านของเรานั้นมีสองแห่ง แห่งแรกคือที่ซึ่งเราย่ำเท้าอยู่ อีกแห่งนั้นอยู่ในใจ ผู้ที่โชคดีอาจไม่รู้สึกถึงความแตกต่างระหว่างบ้านทั้งสอง แต่อย่างไรก็ดี ดวงวิญญาณทั้งหลายต้องทนทุกข์อยู่กับความขัดแย้งในสองสิ่งที่ว่านี้ และอาจถูกทอดทิ้งโดยปราศจากความหวังที่จะได้กลับไปเยือนผืนแผ่นดินในความทรงจำอีกครั้ง แม้หัวใจจะไม่เต็มใจที่จะจากไป ก็ไม่มีทางอื่นอยู่ดี\n                                                                                                                       —เบธเลเฮม",
  str_quest_base_desc_110 = "ฉันเชื่อว่าแผ่นดินแห่งนั้นจะช่วยให้เธอเติบโตขึ้น ย้ำเตือนให้ระลึกถึงสรรพสิ่งทั้งมวลและนำพาไปสู่ความสุขสงบ จุดหมายปลายทางของเธออยู่ข้างหน้านี้แล้ว จงปล่อยวางความขุ่นเคืองและเกลียดชังไว้เบื้องหลัง ปล่อยให้มันอันตรธานหายไป หวังว่าเมื่อเราพบกันในครั้งต่อไป เธอจะเปลี่ยนแปลงเป็นคนใหม่\n                                                                                                                       —เบธเลเฮม",
  str_quest_base_desc_111 = "รัตติกาลนิรันดร์ ดินแดนที่ไม่มีออโรเรียนที่ไหนอยากเฉียดเข้าไปใกล้ มันคือขุมนรกที่ถูกความมืดกัดกร่อน ขณะที่เพลงบรรเลงสนธยาดังขึ้น จงฉวยโอกาสหลบหนีไปซะ ผู้บังคับการโคลอสซัส จงฝ่าทะลุความมืดออกไป ขอความปรารถนาของเธอจงได้รับการเติมเต็ม\n\n-- เบธเลเฮม",
  str_quest_base_desc_112 = "ความหวังมักมาพร้อมกับบททดสอบเสมอ เหมือนดั่งดอกไม้ที่ปกคลุมด้วยหนามแหลม ถ้าเธอพร้อมที่จะเจ็บช้ำไปทั่วร่าง ก็จงกลับไปที่จุดเริ่มต้นอีกครั้ง เพื่อที่จะแสวงหา พ่ายแพ้ สิ้นหวัง และท้ายที่สุด คือเพื่อให้เธอเชิดหน้าได้อีกครั้ง\n\n—เบธเลเฮม",
  str_quest_base_desc_113 = "คมดาบแห่งความจริงทิ่มแทงทะลุหน้าอก เชือดเฉือนหัวใจที่เปราะบางให้สลายเป็นชิ้น ๆ \"เป็นไปได้ยังไง?\" \"เป็นไปไม่ได้!\" ตกใจ สงสัย ขุ่นเคืองใจ ได้แต่จ้องมองความว่างเปล่าอยู่ข้างห้วงเหวที่สูญหาย ฉันมองไม่เห็นทางเลือกของเธอเลย เคเลสไทต์ ฉันมองไม่เห็นอะไรทั้งนั้น\n\n--เบธเลเฮม",
  str_quest_base_desc_114 = "ทุกคนแสวงหาความรู้ในชีวิตอย่างต่อเนื่อง คุณโชคดีแต่ก็น่าสมเพชเช่นกัน โชคชะตาเปิดโอกาสให้คุณสำรวจได้มากขึ้น คุณสามารถไปได้ไกลกว่าคนส่วนใหญ่ แต่มันเป็นการเดินทางที่เปล่าเปลี่ยว ฉันไม่รู้ว่าคุณจะลงเอยที่ใด เพราะปลายทางของคุณอยู่ไกลเกินกว่าที่ฉันมองเห็น\n—เบธเลเฮม",
  str_quest_base_desc_115 = "คุณสังเกตไหมว่าคุณเริ่มพบปะผู้คนมากขึ้นเรื่อยๆ? มีจุดกำเนิดและปลายทางที่แตกต่างกัน ผู้คนมากมายอาศัยอยู่ใต้ท้องฟ้า ผู้โชคดีที่มีดวงอาทิตย์อยู่เหนือศีรษะจะได้รับแสงแดดมากที่สุด แต่ผู้ที่ยืนอยู่ในแสงสนธยาคือผู้ที่อยู่ห่างจากดวงอาทิตย์มากที่สุด\n—เบธเลเฮม",
  str_quest_base_desc_116 = "ช่างเป็นโชคชะตาที่พลิกผันอย่างน่าขันที่บังคับให้คุณต้องอยู่ร่วมกับศัตรูเก่า ไม่ว่าทะเลเพลิงหรือหลุมลึกจะอยู่ข้างหน้า ไม่มีทางเลือกอื่นนอกจากเผชิญหน้ากับเพื่อนของคุณ\n—เบธเลเฮม",
  str_quest_base_desc_117 = "สนามรบเป็นเวทีสำหรับนักวางแผน และผู้ชมที่โง่เขลาแห่กันไปจากทุกทิศทุกทาง ค่ำคืนอันไร้ขอบเขตใกล้เข้ามา แต่ Aurorian ยังไม่ตื่นจากความฝันอันแสนหวานของพวกเขา\n—เบธเลเฮม",
  str_quest_base_desc_118 = "ในขณะที่อำนาจกำลังเปลี่ยนแปลง บุคคลที่ถูกลืมโดยชะตากรรมก็ขึ้นมายืนอยู่บนเวทีโลกใต้สายตาของหลายคน แต่ความทะเยอทะยานกลับเป็นอาวุธที่ไร้ประโยชน์ที่สุดในสนามรบ: ต้องการฆ่าตัวเก่าของตัวเองเสียก่อน จึงจะสามารถหลุดพ้นจากห้วงน้ำวนของการเมืองและได้ชีวิตใหม่ที่เติมเต็ม\n—เบธเลเฮม",
  str_quest_base_desc_119 = "ความแข็งแกร่งมาจากการขับเคี่ยวตัวเองหรือการให้โอกาสจากคนอื่น? จนกระทั่งคุณเห็นรูปทรงอันโด่งดังตัวต่อตัวในห้วงโคลน ขุดหลุมฝังตัวเอง คุณจะรู้ในที่สุดว่าความเปราะบางคือสาระสำคัญของชีวิต\n—เบธเลเฮม",
  str_quest_base_desc_120 = "หลังจากมากกว่า 600 ปี สุดท้ายแล้วมีการติดต่อจากองค์กรต่างด้าวกับอิลลูมินา ควรหันไปเล่นหน้าหนังสือประวัติศาสตร์เพื่อค้นหาความเป็นไปได้หรือควรละทิ้งอดีตและสร้างทางใหม่? นั่นคือคำถามที่ต้องตัดสินใจ และเป็นปริศนาที่ทำให้ชาวออโรเรียนหลายรุ่นตกอยู่ในความสับสน\n-เบธเลเฮม-",
  str_quest_base_desc_121 = "คุณได้ใช้เวลาอันนับไม่ถ้วนกับเพื่อนๆ ในช่วงเวลาที่มีความสุข แต่คุณไม่เคยคิดว่าเวลาที่จะต้องลากันจะมาถึงเร็วเกินคาด สัญญาณจากอดีตได้กลับมาอีกครั้ง ครั้งนี้คุณต้องกลายเป็นคนที่แข็งแกร่งและสำรวจอดีตของคุณในซากปรักหักพังที่ไม่รู้จัก\n—เบธเลเฮม",
  str_quest_base_desc_122 = "\"เพื่อสร้างเสาไฟตามทางที่จะผ่าน,\" ฉันพูดอย่างนี้ ในฐานะราชินีแห่งแดนเหนือ\n—เบธเลเฮม",
