  str_quest_base_achieve_finish_list_title = "เควสต์ที่เสร็จสิ้น",
  str_quest_base_desc_123 = "คุณได้เห็นความมืดที่ไม่มีวันสิ้นสุดแล้ว—คุณได้เตรียมความมุ่งมั่นในหัวใจของคุณหรือยัง? จำนวนมากของวิญญาณติดอยู่ในสถานการณ์ที่ไม่มีทางออกของแชโดว์ ไล่ตามความหวังที่สั้นชั่ว แต่สำหรับคุณ ความหวังนั้นเป็นจริง\nคุณจะคว้ามัน เพราะเรื่องราวนี้เริ่มต้นด้วยขั้นตอนแรกของคุณในฐานะฮีโร่ คุณจะทหารยามประกายไฟแห่งความหวังนั้น และเป็นผลมาจากคุณ มันจะยืนยัง ศรัทธาในสิ่งนี้ และก้าวไปข้างหน้าด้วยความศรัทธาที่ไม่สั่นสะเทือน\n—เบธเลเฮม",
